   110  void OrfDecoder::decodeUncompressed(const ByteStream& s, uint32 w, uint32 h,
   111                                      uint32 size) {
   112    UncompressedDecompressor u(s, mRaw);
   113    if (hints.has("packed_with_control"))
   114      u.decode12BitRaw<little, false, true>(w, h);
   115    else if (hints.has("jpeg32_bitorder")) {
   116      iPoint2D dimensions(w, h);
   117      iPoint2D pos(0, 0);
   118      u.readUncompressedRaw(dimensions, pos, w * 12 / 8, 12, BitOrder_MSB32);
   119    } else if (size >= w*h*2) { // We're in an unpacked raw
   120      if (s.isInNativeByteOrder())
   121        u.decodeRawUnpacked<12, little>(w, h);
   122      else
   123        u.decode12BitRawUnpackedLeftAligned<big>(w, h);
   124    } else if (size >= w*h*3/2) { // We're in one of those weird interlaced packed raws
   125      u.decode12BitRaw<big, true>(w, h);
   126    } else {
   127      ThrowRDE("Don't know how to handle the encoding in this file");
   128    }
   129  }
