    82  std::unique_ptr<RawDecoder> TiffParser::makeDecoder(TiffRootIFDOwner root,
    83                                                      const Buffer& data) {
    84    const Buffer* mInput = &data;
    85    if (!root)
    86      ThrowTPE("TiffIFD is null.");
    87
    88    for (const auto& decoder : Map) {
    89      checker_t dChecker = nullptr;
    90      constructor_t dConstructor = nullptr;
    91
    92      std::tie(dChecker, dConstructor) = decoder;
    93
    94      assert(dChecker);
    95      assert(dConstructor);
    96
    97      if (!dChecker(root.get(), mInput))
    98        continue;
    99
   100      return dConstructor(move(root), mInput);
   101    }
   102
   103    ThrowTPE("No decoder found. Sorry.");
   104    return nullptr;
   105  }
