   107  template <class Decoder>
   108  std::unique_ptr<RawDecoder> TiffParser::constructor(TiffRootIFDOwner&& root,
   109                                                      const Buffer* data) {
   110    return make_unique<Decoder>(std::move(root), data);
   111  }
