    42  void TiffIFD::parseIFDEntry(ByteStream* bs) {
    43    TiffEntryOwner t;
    44
    45    auto origPos = bs->getPosition();
    46
    47    try {
    48      t = make_unique<TiffEntry>(this, bs);
    49    } catch (IOException&) { // Ignore unparsable entry
    50      // fix probably broken position due to interruption by exception
    51      // i.e. setting it to the next entry.
    52      bs->setPosition(origPos + 12);
    53      return;
    54    }
    55
    56    try {
    57      switch (t->tag) {
    58      case DNGPRIVATEDATA:
    59        add(parseDngPrivateData(t.get()));
    60        break;
    61
    62      case MAKERNOTE:
    63      case MAKERNOTE_ALT:
    64        add(parseMakerNote(t.get()));
    65        break;
    66
    67      case FUJI_RAW_IFD:
    68      case SUBIFDS:
    69      case EXIFIFDPOINTER:
    70        for (uint32 j = 0; j < t->count; j++)
    71          add(make_unique<TiffIFD>(this, *bs, t->getU32(j)));
    72        break;
    73
    74      default:
    75        add(move(t));
    76      }
    77    } catch (RawspeedException&) { // Unparsable private data are added as entries
    78      add(move(t));
    79    }
    80  }
