   105  TiffRootIFDOwner TiffIFD::parseDngPrivateData(TiffEntry* t) {
   106    /*
   107    1. Six bytes containing the zero-terminated string "Adobe". (The DNG specification calls for the DNGPrivateData tag to start with an ASCII string identifying the creator/format).
   108    2. 4 bytes: an ASCII string ("MakN" for a Makernote),  indicating what sort of data is being stored here. Note that this is not zero-terminated.
   109    3. A four-byte count (number of data bytes following); this is the length of the original MakerNote data. (This is always in "most significant byte first" format).
   110    4. 2 bytes: the byte-order indicator from the original file (the usual 'MM'/4D4D or 'II'/4949).
   111    5. 4 bytes: the original file offset for the MakerNote tag data (stored according to the byte order given above).
   112    6. The contents of the MakerNote tag. This is a simple byte-for-byte copy, with no modification.
   113    */
   114    ByteStream& bs = t->getData();
   115    if (!bs.skipPrefix("Adobe", 6))
   116      ThrowTPE("Not Adobe Private data");
   117
   118    if (!bs.skipPrefix("MakN", 4))
   119      ThrowTPE("Not Makernote");
   120
   121    bs.setInNativeByteOrder(big == getHostEndianness());
   122    uint32 makerNoteSize = bs.getU32();
   123    if (makerNoteSize != bs.getRemainSize())
   124      ThrowTPE("Error reading TIFF structure (invalid size). File Corrupt");
   125
   126    bs.setInNativeByteOrder(isTiffInNativeByteOrder(bs, 0, "DNG makernote"));
   127    bs.skipBytes(2);
   128
   129    uint32 makerNoteOffset = bs.getU32();
   130    makerNoteSize -= 6; // update size of orinial maker note, we skipped 2+4 bytes
   131
   132    // Update the underlying buffer of t, such that the maker note data starts at its original offset
   133    bs.rebase(makerNoteOffset, makerNoteSize);
   134
   135    return parseMakerNote(t);
   136  }
