   211  std::vector<const TiffIFD*> TiffIFD::getIFDsWithTag(TiffTag tag) const {
   212    vector<const TiffIFD*> matchingIFDs;
   213    if (entries.find(tag) != entries.end()) {
   214      matchingIFDs.push_back(this);
   215    }
   216    for (auto& i : subIFDs) {
   217      vector<const TiffIFD*> t = i->getIFDsWithTag(tag);
   218      matchingIFDs.insert(matchingIFDs.end(), t.begin(), t.end());
   219    }
   220    return matchingIFDs;
   221  }
   222
   223  const TiffIFD* TiffIFD::getIFDWithTag(TiffTag tag, uint32 index) const
   224  {
   225    auto ifds = getIFDsWithTag(tag);
   226    if (index >= ifds.size())
   227      ThrowTPE("failed to find %u ifs with tag 0x%04x", index + 1, tag);
   228    return ifds[index];
   229  }
