    85  TiffEntry::TiffEntry(TiffIFD* parent_, TiffTag tag_, TiffDataType type_,
    86                       uint32 count_, ByteStream&& data_)
    87      : parent(parent_), data(std::move(data_)), tag(tag_), type(type_),
    88        count(count_) {
    89    // check for count << datashift overflow
    90    if (count > UINT32_MAX >> datashifts[type])
    91      ThrowTPE("integer overflow in size calculation.");
    92
    93    uint32 bytesize = count << datashifts[type];
    94
    95    if (data.getSize() != bytesize)
    96      ThrowTPE("data set larger than entry size given");
    97  }
