   146  uint32 TiffEntry::getU32(uint32 index) const {
   147    if (type == TIFF_SHORT)
   148      return getU16(index);
   149
   150    switch (type) {
   151    case TIFF_LONG:
   152    case TIFF_OFFSET:
   153    case TIFF_BYTE:
   154    case TIFF_UNDEFINED:
   155    case TIFF_RATIONAL:
   156    case TIFF_SRATIONAL:
   157      break;
   158    default:
   159      ThrowTPE("Wrong type %u encountered. Expected Long, Offset, Rational or "
   160               "Undefined on 0x%x",
   161               type, tag);
   162      break;
   163    }
   164
   165    return data.peek<uint32>(index);
   166  }
