   210  string TiffEntry::getString() const {
   211    if (type != TIFF_ASCII && type != TIFF_BYTE)
   212      ThrowTPE("Wrong type 0x%x encountered. Expected Ascii or Byte", type);
   213
   214    // *NOT* ByteStream::peekString() !
   215    const auto bufSize = data.getRemainSize();
   216    const auto* buf = data.peekData(bufSize);
   217    const auto* s = reinterpret_cast<const char*>(buf);
   218    return string(s, strnlen(s, bufSize));
   219  }
