   221  const DataBuffer &TiffEntry::getRootIfdData() const {
   222    TiffIFD* p = parent;
   223    TiffRootIFD* r = nullptr;
   224    while (p) {
   225      r = dynamic_cast<TiffRootIFD*>(p);
   226      if (r)
   227        break;
   228      p = p->parent;
   229    }
   230    if (!r)
   231      ThrowTPE("Internal error in TiffIFD data structure.");
   232
   233    assert(r != nullptr);
   234    return r->rootBuffer;
   235  }
